+	memset(&adapter_diag, 0, sizeof(adapter_diag));
+	upper_rx_ready = NULL;
+	rx_read = 0;
+	rx_write = 0;
+	rx_count = 0;
+	mbox0_drv_ready_callback_register(mbox0_rx_ready);
+	return mbox0_drv_callback_register(mbox0_rx_isr);
